INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7284437, 1134530, 104230, '<td valign="top">I love how the shadows appear stationary, although if I twist my head to look at the people you can tell that they are walking. Great background.  In my top three.  Hope to see it ribbon.</td>', 'I love how the shadows appear stationary, although if I twist my head to look at the people you can tell that they are walking. Great background.  In my top three.  Hope to see it ribbon.', '2014-11-11 23:05:18.000000', NULL, 1),
(7284515, 1134699, 175381, '<td valign="top">Congratulation for the ribbon</td>', 'Congratulation for the ribbon', '2014-11-12 00:04:20.000000', NULL, 0),
(7284516, 1134896, 175381, '<td valign="top">Congratulation for the ribbon</td>', 'Congratulation for the ribbon', '2014-11-12 00:05:14.000000', NULL, 0),
(7284517, 1134664, 175381, '<td valign="top">Congratulation for the ribbon</td>', 'Congratulation for the ribbon', '2014-11-12 00:05:46.000000', NULL, 0),
(7284542, 1134530, 108069, '<td valign="top">Really cool photo, John.</td>', 'Really cool photo, John.', '2014-11-12 00:35:22.000000', NULL, 0),
(7284550, 1134864, 74588, '<td valign="top">hah</td>', 'hah', '2014-11-12 01:00:04.000000', NULL, 0),
(7284555, 1134896, 37858, '<td valign="top">Your lighting is superb and the image is crisp without being the least bit overdone.  When I grow up I want to be able to do this too (the photography, not the flip).  Since I''m in my 60''s I''m not sure I''ll ever get there.  But it''s clear you have it all figured out.  Wonderful image.</td>', 'Your lighting is superb and the image is crisp without being the least bit overdone.  When I grow up I want to be able to do this too (the photography, not the flip).  Since I''m in my 60''s I''m not sure I''ll ever get there.  But it''s clear you have it all figured out.  Wonderful image.', '2014-11-12 01:16:33.000000', NULL, 0),
(7284599, 1134699, 156466, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by PennyClick:</b></div><hr/><i> Great image. Well seen. Love the tones, and the splash of red.  Did you consider a horizontal flip? I know I would have done just to see if I preferred a left to right flow within the image rather than the right to left one we see here.  Ties with one other image for my highest score and I hope to see it ribbon. </i></td></tr></table> <br/> <br/>Penny, yes indeed, I did try it flipped horizontally.  In fact, my initial edit was done this way because I did a 180 degree rotation of the original image. I liked it just fine, but then decided to try it the other way, because it is the same basic angle that I saw the room from in the first place.  When I did I found that I preferred this one.  Why?  Perhaps because it reminded me of the original, unflipped view, and maybe because I felt the left-to-right leading line was a little more traditional, where the right-to-left felt "off" in a good way and might help with the disorienting of the viewer and delay the discovery that this was actually upside down.</td>', 'Originally posted by PennyClick: Great image. Well seen. Love the tones, and the splash of red.  Did you consider a horizontal flip? I know I would have done just to see if I preferred a left to right flow within the image rather than the right to left one we see here.  Ties with one other image for my highest score and I hope to see it ribbon.   Penny, yes indeed, I did try it flipped horizontally.  In fact, my initial edit was done this way because I did a 180 degree rotation of the original image. I liked it just fine, but then decided to try it the other way, because it is the same basic angle that I saw the room from in the first place.  When I did I found that I preferred this one.  Why?  Perhaps because it reminded me of the original, unflipped view, and maybe because I felt the left-to-right leading line was a little more traditional, where the right-to-left felt "off" in a good way and might help with the disorienting of the viewer and delay the discovery that this was actually upside down.', '2014-11-12 05:38:18.000000', NULL, 0),
(7284600, 1134896, 156466, '<td valign="top">Congratulations on the Blue!!  Great image.</td>', 'Congratulations on the Blue!!  Great image.', '2014-11-12 05:39:29.000000', NULL, 0),
